let menuExpanded=false,missingCells=[],data=window.PCBL_SNAPSHOT,season='S3',view='home',playerTab='stats',differencePair='S1:S2',category='hitting',stat='OPS',comparePicks=[{name:'Auden',season:'S3'},{name:'Jarvis',season:'S3'}],graphDots=[],ripples=[],pointer=null,chartRAF=0,lastRipple=0;
