function csvParse(text){let rows=[],row=[],cell='',quotes=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quotes&&text[i+1]==='"'){cell+='"';i++}else quotes=!quotes}else if(c===','&&!quotes){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quotes){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}return rows}
function parseSheet(rows,columns=COLUMNS){let out={};missingCells=[];for(let [label,code] of [['CAREER','ALL TIME'],...rows.map(r=>(r[0]||'').trim().toUpperCase()).filter(k=>/^SEASON \d+$/.test(k)).map(k=>[k,'S'+k.split(' ')[1]])]){let ix=rows.findIndex(r=>(r[0]||'').trim().toUpperCase()===label);if(ix<0){if(label==='CAREER')continue;throw Error('Missing '+label)};let header=rows[ix-1]||[],players=[],sheetOffset=rows.length<190?(({'ALL TIME':39,S1:80,S2:121,S3:162}[code]??(ix+1))-(ix+1)):0;for(let [name,col] of Object.entries(columns)){let record=(header[col]||'').match(/\((\d+-\d+)\)/),stats={hitting:{},pitching:{},overall:{}},phase='';for(let j=ix+1;j<Math.min(ix+40,rows.length);j++){let row=rows[j],key=(row[0]||'').trim().toUpperCase(),raw=String(row[col]||'').trim();if(/^TWR\b/.test(key))continue;if(key==='HITTING'||key==='PITCHING'){phase=key.toLowerCase();continue}if(/^SEASON \d+$/.test(key)||key==='PLAYER'||key.startsWith('---'))break;if(!phase)continue;key=({'BA':'AVG','HA (HITS AGAINST)':'HA','HRA (HR AGAINST)':'HRA','RA (RUNS-AGAINST)':'RA'})[key]||key;if(/^3RD\+?\s*(?:INN\.?|INNING)/.test(key))key='LATE RUNS';if(phase==='pitching'&&key==='SV/SVO'){let m=raw.match(/^(\d+)\s*\/\s*(\d+)/);if(m){stats.pitching.SV=Number(m[1]);stats.pitching.SVO=Number(m[2]);stats.pitching['SV%']=m[2]==='0'?undefined:Number(m[1])/Number(m[2])*100}else if(/^0(?:\.0+)?$/.test(raw)){stats.pitching.SV=0;stats.pitching.SVO=0}continue}if(phase==='pitching'&&key==='DP'){let m=raw.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))/);if(m)stats.pitching.DP=Number(m[1]);continue}let match=raw.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))/);if(match&&[...CATALOG.hitting,...CATALOG.pitching].some(x=>x[0]===key))stats[phase][key]=Number(match[1]);else if(!match&&rows.length<190&&window.PCBL_SNAPSHOT?.[code]?.find(x=>x.name===name)?.stats?.[phase]?.[key]!==undefined)missingCells.push({code,name,side:phase,key,range:String.fromCharCode(65+col)+(j+1+sheetOffset)})}if((stats.hitting.PA||0)>0||(stats.pitching.IP||0)>0){let h=stats.hitting,old=window.PCBL_SNAPSHOT?.[code]?.find(x=>x.name===name)?.stats;for(let side of ['hitting','pitching','overall'])for(let [key,value] of Object.entries(old?.[side]||{}))if(stats[side][key]===undefined)stats[side][key]=value;if(h.AVG===undefined&&h.AB>0&&h.H!==undefined)h.AVG=+(h.H/h.AB).toFixed(3);if(h.SLG===undefined&&h.AB>0&&['H','2B','3B','HR'].every(k=>h[k]!==undefined))h.SLG=+((h.H+h['2B']+2*h['3B']+3*h.HR)/h.AB).toFixed(3);if(h.ISO===undefined&&h.SLG!==undefined&&h.AVG!==undefined)h.ISO=+(h.SLG-h.AVG).toFixed(3);if(h.OPS===undefined&&h.OBP!==undefined&&h.SLG!==undefined)h.OPS=+(h.OBP+h.SLG).toFixed(3);players.push({name,record:record?.[1]||window.PCBL_SNAPSHOT?.[code]?.find(x=>x.name===name)?.record||null,stats})}}out[code]=players}for(let p of out['ALL TIME']||[]){let wins=0,losses=0,found=false;for(let season of Object.keys(out).filter(k=>/^S\d+$/.test(k))){let rec=out[season]?.find(x=>x.name===p.name)?.record?.match(/^(\d+)-(\d+)$/);if(rec){wins+=+rec[1];losses+=+rec[2];found=true}}if(found)p.record=wins+'-'+losses}return out}
function roster(s=season){return data[s]||[]};function player(name,s=season){return roster(s).find(p=>p.name===name)}
function eligible(p,c){if(!p)return false;if(c==='hitting')return (p.stats.hitting.PA||0)>0;if(c==='pitching')return (p.stats.pitching.IP||0)>0;return true}
