function advanced(p,s){if(!eligible(p,'hitting'))return {};let h=p.stats.hitting,A=h.AB,H=h.H,HR=h.HR,K=h.K,BB=h.BB,PA=h.PA,B2=h['2B'],B3=h['3B'];let singles=H-B2-B3-HR,lg=leagueRates(s);return {'ISO':h.SLG!==undefined&&h.AVG!==undefined?h.SLG-h.AVG:h.ISO,'AB/HR':HR>0?safe(A,HR):undefined,'BABIP*':safe(H-HR,A-K-HR),'OPS+':lg.obp&&lg.slg?100*(h.OBP/lg.obp+h.SLG/lg.slg-1):undefined,'BB%':safe(BB,PA)*100,'K%':safe(K,PA)*100,'HR/PA':safe(HR,PA),'XBH%':safe(B2+B3+HR,H)*100,'TB':singles+2*B2+3*B3+4*HR,'BB/K':safe(BB,K)}}
function pitchingAdvanced(p,s){return window.PCBLPitchingAdvanced?.metrics?.(p,s,{park:p?.park||'ALL',phase:p?.phase||'regular'})||{}}
function val(p,c,k,s){if(!eligible(p,c))return undefined;if(c==='overall')return p.stats.overall?.[k];if(c==='record'){let m=String(p.record||'').match(/^(\d+)-(\d+)/);if(!m)return undefined;let w=+m[1],l=+m[2];return k==='W'?w:k==='L'?l:k==='WIN%'?safe(w,w+l):undefined}if(c==='hitting'&&ADV.some(x=>x[0]===k))return p.source==='GAME LOG SPLIT'&&k==='OPS+'?undefined:advanced(p,s)[k];if(c==='pitching'&&PITCH_ADV.some(x=>x[0]===k))return pitchingAdvanced(p,s)[k];if(c==='pitching'&&['HRA/3','HA/3','BB/3','HBP/3'].includes(k)){let n=p.stats.pitching[k.split('/')[0]];return Number.isFinite(n)?safe(n*3,p.stats.pitching.IP):undefined}return p.stats[c]?.[k]}
function fmt(n,k){if(n===undefined||n===null||!Number.isFinite(n))return '—';if(['OPS+','ERA+','FIP+'].includes(k))return n.toFixed(0);if(['BB%','K%','K-BB%','HBP%','HR%','XBH%','SV%','POSTWIN%'].includes(k))return n.toFixed(1)+'%';if(['AVG','OBP','SLG','OPS','ISO','BABIP*','HR/PA','WIN%','OAVG','OOBP','OSLG','OOPS','OISO'].includes(k))return n.toFixed(3).replace(/^0\./,'.');if(['ERA','WHIP','FIP','SIERA','K/3','AB/HR','BB/K','HRA/3','HA/3','BB/3','HBP/3'].includes(k))return n.toFixed(2);if(k==='IP')return String(+n.toFixed(1));return Number.isInteger(n)?String(n):n.toFixed(1)}
