function paintOverviewLeaders(){let selected=$('overviewSeason').value,rows=[['hitting','OPS','OPS'],['hitting','HR','HOME RUNS'],['hitting','AVG','AVERAGE'],['pitching','ERA','ERA'],['pitching','WHIP','WHIP'],['pitching','K','STRIKEOUTS'],['record','W','RECORD']];$('overviewLeaders').innerHTML=rows.map(([side,key,title])=>{let names=roster(selected).filter(p=>side==='record'?/^\d+-\d+$/.test(p.record||''):val(p,side,key,selected)!==undefined).sort((a,b)=>side==='record'?((+b.record.split('-')[0])-(+a.record.split('-')[0])||(+a.record.split('-')[1])-(+b.record.split('-')[1])):LOWER.has(key)?val(a,side,key,selected)-val(b,side,key,selected):val(b,side,key,selected)-val(a,side,key,selected));return `<article class="overview-card"><small>${side.toUpperCase()} / ${esc(title)}</small>${names.slice(0,3).map((p,i)=>`<div><span>${i+1}</span><strong style="color:${COLORS[p.name]}">${esc(p.name)}</strong><b>${side==='record'?esc(p.record):fmt(val(p,side,key,selected),key)}</b></div>`).join('')||'<p class="hint">No data</p>'}</article>`}).join('')}
const FULL_SEASON_GAMES=6,RECENCY_DECAY=.6;
function seasonHistory(target=4){return Object.keys(data).filter(k=>/^S\d+$/.test(k)&&Number(k.slice(1))<target).sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)))}
function gamesPlayed(p){let m=p?.record?.match(/^(\d+)-(\d+)$/);return m?Number(m[1])+Number(m[2]):0}
function weightedForecast(name,side,measure,volume=false,target=4){let codes=seasonHistory(target),latest=Number(codes.at(-1)?.slice(1));let values=codes.map(code=>{let p=player(name,code),value=p?measure(p):undefined,exposure=volume?gamesPlayed(p):p?.stats[side]?.[side==='hitting'?'PA':'IP'];return {value,w:Math.pow(RECENCY_DECAY,latest-Number(code.slice(1)))*(Number.isFinite(exposure)&&exposure>0?exposure:0)}}).filter(x=>Number.isFinite(x.value)&&x.w>0);let weight=values.reduce((sum,x)=>sum+x.w,0);return weight?values.reduce((sum,x)=>sum+x.w*x.value,0)/weight:undefined}
function forecast(name,target=4){let h={},pi={},pa=weightedForecast(name,'hitting',p=>{let g=gamesPlayed(p);return g&&p.stats.hitting.PA>0?FULL_SEASON_GAMES*p.stats.hitting.PA/g:undefined},true,target),rawIP=weightedForecast(name,'pitching',p=>{let g=gamesPlayed(p);return g&&p.stats.pitching.IP>0?FULL_SEASON_GAMES*p.stats.pitching.IP/g:undefined},true,target),ip=Number.isFinite(rawIP)?Math.round(rawIP*2)/2:undefined;
if(pa>0){h.PA=pa;for(let key of ['AB','H','R','BB','2B','3B','HR','K','HBP']){let rate=weightedForecast(name,'hitting',p=>safe(p.stats.hitting[key],p.stats.hitting.PA),false,target);if(Number.isFinite(rate))h[key]=rate*pa}h.XBH=(h['2B']||0)+(h['3B']||0)+(h.HR||0);h.TB=Number.isFinite(h.H)?h.H+(h['2B']||0)+2*(h['3B']||0)+3*(h.HR||0):undefined;h.AVG=safe(h.H,h.AB);h.OBP=weightedForecast(name,'hitting',p=>p.stats.hitting.PA>0?p.stats.hitting.OBP:undefined,false,target);h.SLG=safe(h.TB,h.AB);h.OPS=Number.isFinite(h.OBP)&&Number.isFinite(h.SLG)?h.OBP+h.SLG:undefined;h.ISO=Number.isFinite(h.SLG)&&Number.isFinite(h.AVG)?h.SLG-h.AVG:undefined;h['AB/HR']=safe(h.AB,h.HR);h['BABIP*']=safe(h.H-h.HR,h.AB-h.K-h.HR);h['BB%']=safe(h.BB,h.PA)*100;h['K%']=safe(h.K,h.PA)*100;h['HR/PA']=safe(h.HR,h.PA);h['XBH%']=safe(h.XBH,h.H)*100;h['BB/K']=safe(h.BB,h.K);h['K/BB']=safe(h.K,h.BB);let lg=leagueRates(seasonHistory(target).at(-1)||'S3');h['OPS+']=lg.obp&&lg.slg&&Number.isFinite(h.OBP)&&Number.isFinite(h.SLG)?100*(h.OBP/lg.obp+h.SLG/lg.slg-1):undefined}
if(ip>0){pi.IP=ip;for(let key of ['K','HA','HRA','RA','BB','HBP']){let rate=weightedForecast(name,'pitching',p=>safe(p.stats.pitching[key],p.stats.pitching.IP),false,target);if(Number.isFinite(rate))pi[key]=rate*ip}pi['NO HITTERS']=FULL_SEASON_GAMES*weightedForecast(name,'pitching',p=>safe(p.stats.pitching['NO HITTERS'],gamesPlayed(p)),false,target);pi.ERA=safe(pi.RA*3,ip);pi.WHIP=safe(pi.HA+pi.BB,ip);pi['K/3']=safe(pi.K*3,ip);for(let key of ['HRA','HA','BB','HBP'])pi[key+'/3']=safe(pi[key]*3,ip)}return {name,hitting:h,pitching:pi}}
const PROJECTED_H=['PA','AB','H','AVG','OBP','SLG','OPS','HR','R','BB','2B','3B','XBH','TB','K','HBP','ISO','AB/HR','K/BB','BABIP*','OPS+','BB%','K%','HR/PA','XBH%','BB/K'];
