function projectionValue(v,k){if(!Number.isFinite(v))return '—';return ['PA','AB','H','HR','R','BB','2B','3B','XBH','TB','K','HBP','HA','HRA','RA','NO HITTERS'].includes(k)?v.toFixed(1):fmt(v,k)}
function projectionTable(people,side,keys){return `<div class="projection-table-wrap"><table class="projection-table"><thead><tr><th>STAT</th>${people.map(p=>`<th style="color:${COLORS[p.name]}">${p.name.toUpperCase()}</th>`).join('')}</tr></thead><tbody>${keys.map(k=>`<tr><td>${esc(k)}</td>${people.map(p=>`<td>${projectionValue(p[side][k],k)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function paintForecast(){let people=['Auden','Jason','Jarvis'].map(name=>forecast(name,4));$('forecastContent').innerHTML=`<div class="forecast-grid">${people.map(p=>`<article class="forecast-card" style="--player:${COLORS[p.name]}"><span>SEASON 4 / PROJECTION</span><h3>${p.name.toUpperCase()}</h3><div class="forecast-main"><div><small>OPS</small><strong>${fmt(p.hitting.OPS,'OPS')}</strong></div><div><small>ERA</small><strong>${fmt(p.pitching.ERA,'ERA')}</strong></div></div><div class="forecast-foot"><div><b>${Math.round(p.hitting.HR||0)}</b> HR</div><div><b>${Math.round(p.pitching.K||0)}</b> K</div><div><b>${Math.round(p.hitting.PA||0)}</b> PA</div><div><b>${fmt(p.pitching.IP,'IP')}</b> IP</div></div></article>`).join('')}</div>`;$('forecastDetails').innerHTML='<h3>HITTING</h3>'+projectionTable(people,'hitting',PROJECTED_H)+'<h3>PITCHING</h3>'+projectionTable(people,'pitching',PROJECTED_P);paintLeagueAverage()}
function seasonCodes(){return Object.keys(data).filter(k=>/^S\d+$/.test(k)).sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)))}
function syncSeasonOptions(){const codes=[...new Set([...seasonCodes(),'S4','S5'])].sort((a,b)=>Number(a.slice(1))-Number(b.slice(1)));for(const id of ['season','overviewSeason','graphSeason','playerSeason','dbSeason','leaderSeason','leagueAverageSeason','versusSeason']){const el=document.getElementById(id);if(!el)continue;const original=[...el.options].filter(o=>!/^S\d+$/.test(o.value)).map(o=>[o.value,o.textContent]);const existing=el.value;setOptions(el,[...original,...codes.map(code=>[code,'SEASON '+code.slice(1)])],existing)};for(const el of document.querySelectorAll('select[data-season-extended]')){const current=el.value;setOptions(el,codes.map(code=>[code,code]),current)}}
function leagueRows(selected){return (selected==='ALL TIME'?seasonCodes():[selected]).flatMap(s=>roster(s).map(p=>({p,s}))) }
function leagueAverage(selected){let rows=leagueRows(selected),side=(key,field)=>rows.filter(({p})=>(p.stats[key][field]||0)>0&&gamesPlayed(p)>0),hit=side('hitting','PA'),pitch=side('pitching','IP'),gamesH=hit.reduce((a,{p})=>a+gamesPlayed(p),0),gamesP=pitch.reduce((a,{p})=>a+gamesPlayed(p),0),sum=(profiles,category,key)=>profiles.reduce((a,{p})=>a+(Number(p.stats[category][key])||0),0),h={},pi={};
for(let key of ['PA','AB','H','R','BB','2B','3B','HR','K','HBP'])h[key]=safe(sum(hit,'hitting',key)*FULL_SEASON_GAMES,gamesH);h.XBH=(h['2B']||0)+(h['3B']||0)+(h.HR||0);h.TB=Number.isFinite(h.H)?h.H+(h['2B']||0)+2*(h['3B']||0)+3*(h.HR||0):undefined;h.AVG=safe(h.H,h.AB);let totalPA=sum(hit,'hitting','PA');h.OBP=safe(hit.reduce((a,{p})=>a+(p.stats.hitting.OBP||0)*(p.stats.hitting.PA||0),0),totalPA);h.SLG=safe(h.TB,h.AB);h.OPS=Number.isFinite(h.OBP)&&Number.isFinite(h.SLG)?h.OBP+h.SLG:undefined;h.ISO=h.SLG-h.AVG;h['AB/HR']=safe(h.AB,h.HR);h['BABIP*']=safe(h.H-h.HR,h.AB-h.K-h.HR);h['BB%']=safe(h.BB,h.PA)*100;h['K%']=safe(h.K,h.PA)*100;h['HR/PA']=safe(h.HR,h.PA);h['XBH%']=safe(h.XBH,h.H)*100;h['BB/K']=safe(h.BB,h.K);h['K/BB']=safe(h.K,h.BB);h['OPS+']=selected==='S3'?100:undefined;
for(let key of ['IP','K','HA','HRA','RA','BB','HBP','NO HITTERS'])pi[key]=safe(sum(pitch,'pitching',key)*FULL_SEASON_GAMES,gamesP);pi.IP=Number.isFinite(pi.IP)?Math.round(pi.IP*2)/2:undefined;pi.ERA=safe(sum(pitch,'pitching','RA')*3,sum(pitch,'pitching','IP'));pi.WHIP=safe(sum(pitch,'pitching','HA')+sum(pitch,'pitching','BB'),sum(pitch,'pitching','IP'));pi['K/3']=safe(sum(pitch,'pitching','K')*3,sum(pitch,'pitching','IP'));for(let key of ['HRA','HA','BB','HBP'])pi[key+'/3']=safe(sum(pitch,'pitching',key)*3,sum(pitch,'pitching','IP'));return {h,pi,hitGames:gamesH,pitchGames:gamesP,hitPlayers:hit.length,pitchPlayers:pitch.length}}
function paintLeagueAverage(){let selected=$('leagueAverageSeason').value||'S3',a=leagueAverage(selected),summary=[['AVG',a.h.AVG],['OBP',a.h.OBP],['SLG',a.h.SLG],['OPS',a.h.OPS],['ERA',a.pi.ERA],['WHIP',a.pi.WHIP]];$('leagueAverageContent').innerHTML=`<div class="league-average-summary">${summary.map(([k,v])=>`<div><small>${k}</small><strong>${fmt(v,k)}</strong></div>`).join('')}</div><p class="league-average-caption">${selected==='ALL TIME'?'ALL THREE SEASONS':selected} · ${a.hitGames} HITTING PLAYER-GAMES · ${a.pitchGames} PITCHING PLAYER-GAMES · PROJECTED OVER ${FULL_SEASON_GAMES} GAMES</p><div class="league-average-tables"><section><h3>HITTING / SIX GAMES</h3><div class="average-stat-grid">${PROJECTED_H.filter(k=>k!=='OPS+').map(k=>`<div><span>${k}</span><strong>${projectionValue(a.h[k],k)}</strong></div>`).join('')}</div></section><section><h3>PITCHING / SIX GAMES</h3><div class="average-stat-grid">${PROJECTED_P.map(k=>`<div><span>${k}</span><strong>${projectionValue(a.pi[k],k)}</strong></div>`).join('')}</div></section></div>`;$('leagueAverageMethod').textContent='Each recorded player-season contributes its counted events once. For each side of the ball, projected counting stat = (sum of that stat ÷ total games played by players with recorded PA or IP) × 6. Hitting and pitching use their own player-game totals. AVG = pooled H ÷ AB; SLG = pooled total bases ÷ AB; OBP is the PA-weighted mean of recorded OBP; OPS = OBP + SLG. ERA = 3 × pooled RA ÷ IP; WHIP = (pooled HA + pitching BB) ÷ IP; K/3 = 3 × pooled pitching K ÷ IP. Projected IP rounds to the nearest 0.5; unrounded IP is used for ERA, WHIP, and K/3. Career includes S1, S2, and S3 once each. These are descriptive estimates, not forecasts of future league talent.'}
$('leagueAverageSeason').onchange=paintLeagueAverage;

function whatifScenario(base,pa,ip,target=4){let h={...base.hitting},pi={...base.pitching},hitScale=base.hitting.PA>0?pa/base.hitting.PA:0,pitchScale=base.pitching.IP>0?ip/base.pitching.IP:0;for(let key of ['AB','H','R','BB','2B','3B','HR','K','HBP'])if(Number.isFinite(h[key]))h[key]*=hitScale;h.PA=pa;for(let key of ['K','HA','HRA','RA','BB','HBP'])if(Number.isFinite(pi[key]))pi[key]*=pitchScale;pi.IP=ip;for(let key of ['XBH','TB','AVG','SLG','OPS','ISO','AB/HR','BABIP*','BB%','K%','HR/PA','XBH%','BB/K','K/BB','OPS+'])delete h[key];if(pa>0){h.XBH=(h['2B']||0)+(h['3B']||0)+(h.HR||0);h.TB=Number.isFinite(h.H)?h.H+(h['2B']||0)+2*(h['3B']||0)+3*(h.HR||0):undefined;h.AVG=safe(h.H,h.AB);h.SLG=safe(h.TB,h.AB);h.OPS=Number.isFinite(h.OBP)&&Number.isFinite(h.SLG)?h.OBP+h.SLG:undefined;h.ISO=h.SLG-h.AVG;h['AB/HR']=safe(h.AB,h.HR);h['BABIP*']=safe(h.H-h.HR,h.AB-h.K-h.HR);h['BB%']=safe(h.BB,pa)*100;h['K%']=safe(h.K,pa)*100;h['HR/PA']=safe(h.HR,pa);h['XBH%']=safe(h.XBH,h.H)*100;h['BB/K']=safe(h.BB,h.K);h['K/BB']=safe(h.K,h.BB);let lg=leagueRates(seasonHistory(target).at(-1)||'S3');h['OPS+']=lg.obp&&lg.slg&&Number.isFinite(h.OBP)&&Number.isFinite(h.SLG)?100*(h.OBP/lg.obp+h.SLG/lg.slg-1):undefined}else h.OBP=undefined;
for(let key of ['ERA','WHIP','K/3'])delete pi[key];if(ip>0){pi.ERA=safe(pi.RA*3,ip);pi.WHIP=safe(pi.HA+pi.BB,ip);pi['K/3']=safe(pi.K*3,ip);for(let key of ['HRA','HA','BB','HBP'])pi[key+'/3']=safe(pi[key]*3,ip)}return {name:base.name,hitting:h,pitching:pi}}
function binomialAtLeast(n,p,target){if(target<=0)return 1;if(target>n||p<=0)return 0;if(p>=1)return 1;let term=Math.pow(1-p,n),below=term;for(let k=1;k<target;k++){term*=((n-k+1)/k)*(p/(1-p));below+=term}return Math.max(0,Math.min(1,1-below))}
function poissonAtLeast(lambda,target){if(target<=0)return 1;if(lambda<=0)return 0;let term=Math.exp(-lambda),below=term;for(let k=1;k<target;k++){term*=lambda/k;below+=term}return Math.max(0,Math.min(1,1-below))}
function milestoneOdds(base,pa,ip,stat,target){if(!Number.isInteger(target)||target<1||target>100)return undefined;let h=base.hitting,pi=base.pitching;if(stat==='K')return poissonAtLeast((pi.K/pi.IP)*ip,target);return binomialAtLeast(pa,Math.max(0,Math.min(1,stat==='HR'?h.HR/h.PA:h.R/h.PA)),target)}
function whatifSources(name,target){let codes=seasonHistory(target),latest=Number(codes.at(-1)?.slice(1));let sides=['hitting','pitching'].map(side=>{let metric=side==='hitting'?'PA':'IP',parts=codes.map(code=>{let amount=player(name,code)?.stats?.[side]?.[metric]||0;return {code,w:amount*Math.pow(RECENCY_DECAY,latest-Number(code.slice(1)))}}).filter(x=>x.w>0),total=parts.reduce((sum,x)=>sum+x.w,0);return side.toUpperCase()+' RATE WEIGHTS: '+(total?parts.map(x=>x.code+' '+Math.round(100*x.w/total)+'%').join(' · '):'NO RECORDED '+metric)});return sides.join('  /  ')}
function whatifOptions(){let names=[...new Set(seasonHistory(999).flatMap(code=>roster(code).map(p=>p.name)))].sort((a,b)=>a.localeCompare(b)),chosen=$('whatifPlayer').value;$('whatifPlayer').innerHTML=names.map(name=>`<option value="${esc(name)}">${esc(name.toUpperCase())}</option>`).join('');$('whatifPlayer').value=names.includes(chosen)?chosen:names[0]||''}
function paintWhatif(reset=false){whatifOptions();let name=$('whatifPlayer').value,target=Math.max(3,...seasonHistory(999).map(code=>Number(code.slice(1))))+1,base=forecast(name,target);if(reset){$('whatifPA').max=String(Math.max(180,Math.ceil((base.hitting.PA||0)*2)));$('whatifIP').max=String(Math.max(40,Math.ceil((base.pitching.IP||0)*2)));$('whatifPA').value=String(Math.round(base.hitting.PA||0));$('whatifIP').value=String(base.pitching.IP||0)}let pa=+($('whatifPA').value||0),ip=+($('whatifIP').value||0),a=whatifScenario(base,pa,ip,target);$('whatifPAValue').textContent=pa+' PA';$('whatifIPValue').textContent=fmt(ip,'IP')+' IP';let latest=Number(seasonHistory(target).at(-1)?.slice(1));let historyPA=seasonHistory(target).reduce((sum,code)=>sum+(player(name,code)?.stats.hitting.PA||0),0),historyIP=seasonHistory(target).reduce((sum,code)=>sum+(player(name,code)?.stats.pitching.IP||0),0);$('whatifSource').textContent=`NEXT FULL SEASON ESTIMATE · RECORDED HISTORY THROUGH S${latest}. ${whatifSources(name,target)}.${historyPA<30||historyIP<6?' LIMITED SAMPLE: TREAT THIS FULL-SEASON EXTRAPOLATION CAUTIOUSLY.':''}`;let tiles=(obj,keys)=>keys.map(k=>`<div><span>${k}</span><strong>${projectionValue(obj[k],k)}</strong></div>`).join('');$('whatifResults').innerHTML=`<div class="whatif-summary" style="--player:${COLORS[a.name]}"><div><small>${a.name.toUpperCase()} / NEXT FULL SEASON</small><strong>${pa} PA · ${fmt(ip,'IP')} IP</strong></div>${[['OPS',a.hitting.OPS],['ERA',a.pitching.ERA],['HR',a.hitting.HR],['R',a.hitting.R],['K',a.pitching.K]].map(([k,v])=>`<div><small>${k}</small><strong>${projectionValue(v,k)}</strong></div>`).join('')}</div><div class="whatif-results-grid"><section><h3>HITTING</h3><div class="average-stat-grid">${tiles(a.hitting,PROJECTED_H)}</div></section><section><h3>PITCHING</h3><div class="average-stat-grid">${tiles(a.pitching,PROJECTED_P.filter(k=>k!=='NO HITTERS'))}</div></section></div>`;let stat=$('milestoneStat').value||'HR',targetCount=Number($('milestoneTarget').value),odds=milestoneOdds(base,pa,ip,stat,targetCount),mean=stat==='K'?a.pitching.K:a.hitting[stat],meaning=stat==='HR'?'HOME RUNS':stat==='K'?'PITCHING STRIKEOUTS':'RUNS SCORED';$('milestoneResult').innerHTML=Number.isFinite(odds)?`<div class="milestone-readout"><div class="odds-ring" style="--odds:${(odds*100).toFixed(2)}%"><strong>${(odds*100).toFixed(1)}%</strong></div><div><small>${a.name.toUpperCase()} · AT LEAST ${targetCount} ${meaning}</small><strong>${projectionValue(mean,stat)} PROJECTED ${stat}</strong><p>${pa} PA / ${fmt(ip,'IP')} IP</p></div></div>`:'<p class="hint">Choose a whole-number target from 1 to 100 and a player with recorded data for that stat.</p>'}
$('whatifPlayer').onchange=()=>paintWhatif(true);$('whatifPA').oninput=()=>paintWhatif(false);$('whatifIP').oninput=()=>paintWhatif(false);$('whatifReset').onclick=()=>paintWhatif(true);$('milestoneStat').onchange=()=>{$('milestoneTarget').value=$('milestoneStat').value==='K'?'20':'10';paintWhatif(false)};$('milestoneTarget').oninput=()=>paintWhatif(false);

function statTile(k,n){return `<div class="stat-box"><small>${esc(statLabel(k))}</small><strong>${fmt(n,k)}</strong></div>`}
function expectedRecord(p){let w=gamesPlayed(p),rs=p.stats.hitting.R,ra=p.stats.pitching.RA;if(!w||!Number.isFinite(rs)||!Number.isFinite(ra)||rs+ra<=0)return null;let share=rs*rs/(rs*rs+ra*ra);return (w*share).toFixed(1)+'–'+(w*(1-share)).toFixed(1)}
function paintPlayers(){let playerSeason=$('playerSeason').value||'ALL TIME',selectedPark=$('playerPark').value,playerStage=$('playerStage')?.value||'regular',officialRegular=playerStage==='regular'&&selectedPark==='ALL';let available=officialRegular?roster(playerSeason):Object.keys(COLUMNS).map(name=>window.PCBLParkStats.profile(name,playerSeason,selectedPark,playerStage)).filter(p=>p.games);if(!available.length)available=Object.keys(COLUMNS).map(name=>({name}));setOptions($('playerSelect'),available.map(p=>[p.name,p.name.toUpperCase()]),'Auden');let p=officialRegular?player($('playerSelect').value,playerSeason):window.PCBLParkStats.profile($('playerSelect').value,playerSeason,selectedPark,playerStage);if(!officialRegular&&!p.games&&!window.PCBLRecordStore?.hasGames(p.name,playerSeason,playerStage,selectedPark))p=null;if(!p){$('playerContent').innerHTML=window.PCBLRecordBoard?.render($('playerSelect').value,playerSeason,playerStage,selectedPark)||'<p class="empty">No player data for this game-type / ballpark combination.</p>';return}document.querySelectorAll('.player-tab').forEach(t=>t.classList.toggle('active',t.dataset.playerTab===playerTab));let h=p.stats.hitting,pi=p.stats.pitching,a=advanced(p,playerSeason),stageLabel=playerStage==='regular'?'REGULAR SEASON':playerStage==='postseason'?'POSTSEASON':'REGULAR + POSTSEASON',splitLabel=selectedPark==='ALL'?(officialRegular?'PLAYER FILE':'GAME-LOG SPLIT'):'PARK SPLIT';let header=`<div class="profile-head" style="--player:${COLORS[p.name]}"><div class="profile-identity"><img class="profile-photo" src="assets/players/${p.name.toLowerCase()}.jpg" alt="${esc(p.name)} playing PCBL blitzball" width="128" height="128" loading="lazy" decoding="async"><div><span class="eyebrow">${splitLabel} / ${label(playerSeason)} / ${stageLabel}${selectedPark==='ALL'?'':' / '+esc(selectedPark)}</span><h2>${esc(p.name)}</h2></div></div><strong>${esc(window.PCBLRecordStore?.get(p.name,playerSeason,playerStage,selectedPark).text||'—')}<small> RECORD${officialRegular?'':` · ${p.games} GAME${p.games===1?'':'S'}`}</small></strong></div>${officialRegular?'':`<p class="hint">${selectedPark==='ALL'?stageLabel:Object.entries(p.parks).map(([park,count])=>esc(park)+' · '+count+' GAME'+(count===1?'':'S')).join(' &nbsp;·&nbsp; ')} · LOGGED PLAYS.</p>`}`;let content='';if(playerTab==='stats')content=`<div class="stat-panels"><section class="stat-panel"><h3>HITTING</h3>${eligible(p,'hitting')?`<div class="stat-grid">${CATALOG.hitting.filter(([k])=>!['ISO','AB/HR'].includes(k)).map(([k])=>h[k]===undefined?'':statTile(k,h[k],'hitting',selectedPark)).join('')}</div>${h.PA<20?'<p class="low-pa">'+h.PA+' PA · SMALL HITTING SAMPLE</p>':''}`:'<p class="hint">No plate appearances recorded.</p>'}</section><section class="stat-panel"><h3>PITCHING</h3>${eligible(p,'pitching')?`<div class="stat-grid">${CATALOG.pitching.map(([k])=>val(p,'pitching',k,playerSeason)===undefined?'':statTile(k,val(p,'pitching',k,playerSeason),'pitching',selectedPark)).join('')}</div>`:'<p class="hint">No innings pitched recorded.</p>'}</section></div>`;if(playerTab==='stats'){content+=(window.PCBLSeasonAwards?.render?.(p.name,playerSeason)||'')}
if(playerTab==='advanced'){let pa=pitchingAdvanced(p,playerSeason),pitchGroups=[['RUN PREVENTION',['ERA+','FIP','FIP+','SIERA']],['OUTCOME RATES',['K%','BB%','K-BB%','HBP%','HR%']],['OPPONENT PRODUCTION',['OAVG','OOBP','OSLG','OOPS','OISO']]];content=`<section class="stat-panel advanced-panel"><p class="eyebrow">RATE & DERIVED METRICS</p><div class="expected-record"><span>xW–L</span><strong>${expectedRecord(p)||'—'}</strong><small>Expected wins and losses from runs scored and allowed</small></div><h3>ADVANCED HITTING</h3>${eligible(p,'hitting')?`<div class="stat-grid">${ADV.map(([k])=>statTile(k,a[k],'hitting',selectedPark)).join('')}</div>`:'<p class="hint">No plate appearances recorded.</p>'}<h3 class="advanced-pitching-title">ADVANCED PITCHING</h3>${eligible(p,'pitching')?`${pitchGroups.map(([group,keys])=>{let tiles=keys.map(k=>Number.isFinite(pa[k])?statTile(k,pa[k]):'').join('');return tiles?`<div class="advanced-subgroup"><h4>${group}</h4><div class="stat-grid">${tiles}</div></div>`:''}).join('')}<p class="hint">ERA+/FIP/FIP+ use official pitching totals when available. SIERA and opponent slash are calculated from readable game-log plate appearances.</p>`:'<p class="hint">No innings pitched recorded.</p>'}</section>`;}if(playerTab==='differences')content=officialRegular?differenceHTML(p.name):'<p class="hint">SEASONAL DIFFERENCES USE OFFICIAL REGULAR-SEASON, ALL-BALLPARK STATS. SELECT REGULAR SEASON + ALL BALLPARKS TO VIEW THEM.</p>';$('playerContent').innerHTML=header+(window.PCBLRecordBoard?.render(p.name,playerSeason,playerStage,selectedPark)||'')+content;$('methodContent').innerHTML='<p><b>Hitting:</b> ISO = SLG − AVG; BB% = BB / PA; K% = K / PA; HR/PA = HR / PA; XBH% = (2B + 3B + HR) / H; TB = 1B + 2×2B + 3×3B + 4×HR; BB/K = BB / K; AB/HR = AB / HR. BABIP* omits sacrifice flies because they are not consistently logged. OPS+ is relative to PCBL league offense.</p><p><b>Pitching:</b> ERA+ is league ERA divided by pitcher ERA × 100. PCBL FIP uses the standard HR/BB/HBP/K FIP weights, scaled from a 9-inning to a 3-inning run environment, then given a season-specific constant so league FIP equals league ERA; FIP+ is league FIP divided by pitcher FIP × 100. SIERA uses K, BB and the readable GO/FO/PO out classifications available in the game logs and is shifted to the PCBL league ERA environment.</p><p><b>Game-log limitation:</b> hit trajectories are not recorded consistently, so batted-ball profile percentages are intentionally not displayed. SIERA remains a PCBL-calibrated estimate using the classified out types available in the logs. OPP AVG/OBP/SLG/OPS/ISO are calculated directly from readable plate appearances against the pitcher.</p>'}
function differenceHTML(name){let pair=differencePair,choices=seasonCodes().flatMap((a,i,all)=>all.slice(i+1).map(b=>[a+':'+b,'SEASON '+a.slice(1)+' → '+b.slice(1)])),selector=`<div class="difference-controls"><label for="differencePair">COMPARE SEASONS</label><select id="differencePair">${choices.map(([v,t])=>`<option value="${v}" ${pair===v?'selected':''}>${t}</option>`).join('')}</select></div>`;let [from,to]=pair.split(':'),a=player(name,from),b=player(name,to);if(!a||!b)return selector+'<p class="empty">This player did not appear in both selected seasons.</p>';let fields=[['hitting','OPS'],['hitting','AVG'],['hitting','OBP'],['hitting','SLG'],['hitting','HR/PA'],['hitting','BB%'],['pitching','ERA'],['pitching','ERA+'],['pitching','FIP'],['pitching','FIP+'],['pitching','SIERA'],['pitching','WHIP'],['pitching','K/3']];return selector+`<p class="hint">Each row shows the player's actual season stat. Green means improvement; red means regression. Season 1 → 3 compares those seasons directly.</p><div class="difference-list">${fields.map(([side,key])=>{let x=val(a,side,key,from),y=val(b,side,key,to);if(x===undefined||y===undefined)return '';let diff=y-x,good=lowerBetter(side,key)?diff<0:diff>0;return `<div class="difference-row"><span>${esc(statLabel(key))}</span><strong>${fmt(x,key)} <small>${from}</small></strong><i>→</i><strong>${fmt(y,key)} <small>${to}</small></strong><b class="${diff===0?'':good?'up':'down'}">${diff>0?'+':''}${key.includes('%')?diff.toFixed(1)+'%':diff.toFixed(3)}</b></div>`}).join('')}</div>`}
