function PCBLLiveSheet(response){try{if(response.status!=='ok'||!response.table?.rows)throw Error('Sheet unavailable');let rows=response.table.rows.map(row=>row.c.map(cell=>cell==null?'':String(cell.f??cell.v??''))),parsed=parseSheet(rows);if(!Object.values(parsed).some(a=>a.length))throw Error('No populated seasons');data={...data,...parsed};syncSeasonOptions();window.dispatchEvent(new Event('pcbl-official-stats-updated'));$('sourceStatus').textContent='LIVE SHEET · CHECKING MIXED CELLS';refreshMixedCells()}catch(_){$('sourceStatus').textContent='STATS · LIVE UNAVAILABLE'}}
function fetchCell(item,index){return new Promise(resolve=>{let callback='PCBLCell'+index+'_'+Date.now(),script=document.createElement('script'),timer=setTimeout(()=>finish(false),9000),settled=false;function finish(ok){if(settled)return;settled=true;clearTimeout(timer);delete window[callback];script.remove();resolve(ok)}window[callback]=response=>{let cell=response.table?.rows?.[0]?.c?.[0],raw=String(cell?.f??cell?.v??''),match=raw.trim().match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))/);if(response.status==='ok'){let target=data[item.code]?.find(p=>p.name===item.name)?.stats[item.side];if(target){if(match)target[item.key]=Number(match[1]);else delete target[item.key]}finish(true)}else finish(false)};script.onerror=()=>finish(false);script.src='https://docs.google.com/spreadsheets/d/1-wyh_XRSgYGF8GIynNH1ZYvm__1bf0m7bs0WNNWRmuk/gviz/tq?gid=0&range='+item.range+'&tqx='+encodeURIComponent('out:json;responseHandler:'+callback)+'&_='+Date.now();document.head.appendChild(script)})}
async function refreshMixedCells(){let cells=[...missingCells];if(!cells.length){$('sourceStatus').textContent='LIVE SHEET · UPDATED ON LOAD';sync();return}let checks=await Promise.all(cells.map(fetchCell));$('sourceStatus').textContent=checks.every(Boolean)?'LIVE SHEET · UPDATED ON LOAD':'LIVE SHEET · SOME VALUES SAVED';sync()}
function loadOtherSeasonSheets(){
 const feeds=window.PCBL_SEASON_SOURCES||{};
 for(const [season,settings] of Object.entries(feeds)){
  if(!/^S[4-9]\d*$/.test(season)||!settings||!/^[A-Za-z0-9_-]{20,}$/.test(settings.spreadsheetId||''))continue;
  const handler='PCBLFeed'+season;
  window[handler]=response=>{
   try{
    if(response.status!=='ok'||!response.table?.rows)throw Error('Source unavailable');
    const rows=response.table.rows.map(row=>(row.c||[]).map(cell=>cell==null?'':String(cell.f??cell.v??'')));
    const parsed=parseSheet(rows,settings.columns||COLUMNS);
    if(!parsed[season]?.length)throw Error('Missing '+season+' season section');
    data={...data,[season]:parsed[season]};
    syncSeasonOptions();sync();window.dispatchEvent(new Event('pcbl-official-stats-updated'));
   }catch(e){console.warn('PCBL '+season+' source not accepted:',e);}
  };
  const script=document.createElement('script');
  script.src='https://docs.google.com/spreadsheets/d/'+settings.spreadsheetId+'/gviz/tq?gid='+encodeURIComponent(settings.gid??0)+'&tqx='+encodeURIComponent('out:json;responseHandler:'+handler)+'&_='+Date.now();
  script.onerror=()=>console.warn('PCBL '+season+' sheet unavailable');
  document.head.appendChild(script);
 }
}

