let dbVisible=[],dbSort={key:null,direction:0};
function dbRecord(p,s,phase){return window.PCBLRecordStore?.get(p.name,s,phase,$('dbPark').value)||{text:'—',w:null,l:null,complete:false}}
function dbCell(p,s,key){switch(key){case 'PLAYER':return p.name;case 'SEASON':return s;case 'RECORD':return dbRecord(p,s,$('dbStage').value||'regular').text;case 'REGULAR RECORD':return dbRecord(p,s,'regular').text;case 'POSTSEASON RECORD':return dbRecord(p,s,'postseason').text;case 'ALL GAMES RECORD':return dbRecord(p,s,'both').text;default:return dbField(p,s,key)}}
function dbAllowed(key,side){return ['POSTW','POSTL','POSTWIN%'].includes(key)||[...CATALOG[side],...(side==='hitting'?ADV:PITCH_ADV)].some(([k])=>k===key)}
function dbField(p,s,key){let upper=key.toUpperCase(),side=upper.startsWith('P.')?'pitching':upper.startsWith('H.')?'hitting':dbSide,stat=upper.replace(/^[HP]\./,'');if(['POSTW','POSTL','POSTWIN%'].includes(stat)){const r=dbRecord(p,s,'postseason');if(!r.complete||r.w===null)return undefined;return stat==='POSTW'?r.w:stat==='POSTL'?r.l:(r.w+r.l?100*r.w/(r.w+r.l):undefined)}if(['PLAYER','SEASON','RECORD','REGULAR RECORD','POSTSEASON RECORD','ALL GAMES RECORD'].includes(upper))return undefined;if(!dbAllowed(stat,side))throw Error('Unknown '+side+' stat: '+key);return val(p,side,stat,s)}
function dbCompile(source){if(!source.trim())return ()=>true;let tokens=source.match(/>=|<=|!=|==|[()<>!=]|[^\s()<>!=]+/gi)||[],i=0;function compare(){if(tokens[i]==='('){i++;let inner=or();if(tokens[i++]!==')')throw Error('Missing closing parenthesis');return inner}let key=tokens[i++],op=tokens[i++],raw=tokens[i++];if(!key||!['>','>=','<','<=','=','==','!='].includes(op)||!raw||!Number.isFinite(Number(raw)))throw Error('Use STAT > NUMBER, joined with AND or OR');let n=Number(raw);let field=key.toUpperCase().replace(/^[HP]\./,''),which=/^P\./i.test(key)?'pitching':/^H\./i.test(key)?'hitting':dbSide;if(!dbAllowed(field,which))throw Error('Unknown '+which+' stat: '+key);return (p,s)=>{let v=dbField(p,s,key);if(v===undefined||!Number.isFinite(v))return false;switch(op){case '>':return v>n;case '>=':return v>=n;case '<':return v<n;case '<=':return v<=n;case '!=':return v!==n;default:return v===n}}}function and(){let left=compare();while(tokens[i]?.toUpperCase()==='AND'){i++;let right=compare(),prev=left;left=(p,s)=>prev(p,s)&&right(p,s)}return left}function or(){let left=and();while(tokens[i]?.toUpperCase()==='OR'){i++;let right=and(),prev=left;left=(p,s)=>prev(p,s)||right(p,s)}return left}let result=or();if(i!==tokens.length)throw Error('Unexpected term: '+tokens[i]);return result}
function dbRecords(){let selected=$('dbSeason').value,ss=selected==='SEASONS'?[...new Set([...seasonCodes(),...(window.PCBLRecordStore?.seasons()||[])])].sort((a,b)=>Number(a.slice(1))-Number(b.slice(1))):[selected],park=$('dbPark').value,phase=$('dbStage')?.value||'regular',official=phase==='regular'&&park==='ALL';return ss.flatMap(s=>(official?roster(s):Object.keys(COLUMNS).map(name=>window.PCBLParkStats.profile(name,s,park,phase)).filter(p=>p.games||window.PCBLRecordStore?.hasGames(p.name,s,phase,park))).map(p=>({p,s})))}
function paintDatabase(){let rows=dbRecords(),query=$('dbQuery').value,fields=dbColumns();try{let predicate=dbCompile(query);dbVisible=rows.filter(({p,s})=>predicate(p,s));if(dbSort.key){const key=dbSort.key;dbVisible.sort((a,b)=>{let x=dbCell(a.p,a.s,key),y=dbCell(b.p,b.s,key);if(x==null)return 1;if(y==null)return -1;return dbSort.direction*((typeof x==='number'&&typeof y==='number')?y-x:String(y).localeCompare(String(x),undefined,{numeric:true}))})}let dbPhase=$('dbStage')?.value||'regular',dbOfficial=dbPhase==='regular'&&$('dbPark').value==='ALL',dbSource=dbOfficial?'OFFICIAL REGULAR-SEASON STATS · POSTSEASON W–L INCLUDED':'GAME-LOG SPLITS + VERIFIED POSTSEASON RECORDS · '+(dbPhase==='both'?'REGULAR + POSTSEASON':dbPhase.toUpperCase());$('dbStatus').textContent=dbSource+' · '+dbSide.toUpperCase()+' · '+dbVisible.length+' / '+rows.length+' RECORDS';$('dbStatus').classList.remove('query-error')}catch(e){dbVisible=[];$('dbStatus').textContent=e.message;$('dbStatus').classList.add('query-error')}let heads=fields.map(([label])=>'<th><button type="button" class="db-sort" data-db-sort="'+esc(label)+'" aria-label="Sort by '+esc(statLabel(label))+'">'+esc(statLabel(label))+(dbSort.key===label?(dbSort.direction===1?' ▼':' ▲'):'')+'</button></th>').join('');$('dbHead').innerHTML='<tr>'+heads+'</tr>';$('dbRows').innerHTML=dbVisible.map(({p,s})=>'<tr>'+fields.map(([label,side,key])=>{let raw=dbCell(p,s,label),result=typeof raw==='number'?fmt(raw,key):raw;return '<td'+(label==='PLAYER'?' class="db-player" style="color:'+COLORS[p.name]+'"':'')+'>'+esc(result??'—')+'</td>'}).join('')+'</tr>').join('')||'<tr><td colspan="'+fields.length+'">NO MATCHING RECORDS</td></tr>';document.querySelectorAll('[data-db-sort]').forEach(button=>button.onclick=()=>{const key=button.dataset.dbSort;if(dbSort.key!==key)dbSort={key,direction:1};else if(dbSort.direction===1)dbSort.direction=-1;else dbSort={key:null,direction:0};paintDatabase()})}
document.querySelectorAll('[data-db-side]').forEach(button=>button.onclick=()=>{dbSide=button.dataset.dbSide;dbSort={key:null,direction:0};document.querySelectorAll('[data-db-side]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',String(b===button))});paintDatabase()});$('dbRun').onclick=paintDatabase;$('dbSeason').onchange=paintDatabase;$('dbStage').onchange=paintDatabase;$('dbPark').onchange=paintDatabase;$('dbQuery').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();paintDatabase()}};$('dbQuery').oninput=paintDatabase;$('dbDownload').onclick=()=>download('PCBL_DATABASE.csv',csv([dbColumns().map(([k])=>k),...dbVisible.map(({p,s})=>dbColumns().map(([k,side,key])=>dbCell(p,s,k)))]),'text/csv;charset=utf-8');

window.addEventListener('pcbl-logs-updated',()=>{if(['database','lab','players','compare','leaders'].includes(view))sync()});
